const isTimeWithinDomain = (
  start: Date,
  end: Date,
  domainStart: number,
  domainEnd: number,
) => start.getTime() >= domainStart && end.getTime() <= domainEnd;

const isTimePartiallyWithinDomain = (
  start: Date,
  end: Date,
  domainStart: number,
  domainEnd: number,
) => start.getTime() <= domainEnd && end.getTime() >= domainStart;

export const isDateTimePartiallyOrWithinDomain = (
  start: Date,
  end: Date,
  domainStart: number,
  domainEnd: number,
) =>
  isTimeWithinDomain(start, end, domainStart, domainEnd) ||
  isTimePartiallyWithinDomain(start, end, domainStart, domainEnd);
